protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");

        // EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
        // Preserve the old name so existing 500K documents remain readable and
        // direct SQL queries that reference c.Discriminator keep working.
        entity.HasDiscriminator<string>("Discriminator");

        // EF Core 9 changed the id format from "Product|123" to just "123".
        // Preserve the old compound format so existing documents stay accessible.
        entity.HasRootDiscriminatorInJsonId(true);
    });

    // REMOVED: HasIndex — EF Core 9 Cosmos provider throws for HasIndex.
    // Cosmos DB indexing is managed via the container's indexing policy
    // (Azure Portal / Bicep / Terraform), not through EF Core.
}

